<?php
declare(strict_types=1);require_once __DIR__.'/billing_common.php';$user=billing_require_admin();production_require_method('POST');$in=production_input();accounts_endpoint(function()use($user,$in):array{$db=production_db();return accounts_transaction($db,function()use($db,$user,$in):array{$allocationWhtId=(int)($in['allocation_wht_id']??0);$receiptId=(int)($in['receipt_id']??0);$evidenceId=(int)($in['evidence_id']??0);if($allocationWhtId>0){$find=$db->prepare("SELECT r.id receipt_id FROM qbook_customer_receipt_allocation_wht aw JOIN qbook_customer_receipt_allocations a ON a.id=aw.receipt_allocation_id JOIN qbook_customer_receipts r ON r.id=a.receipt_id WHERE aw.id=? AND aw.certificate_status='CERTIFICATE_PENDING' FOR UPDATE");$find->execute([$allocationWhtId]);$receiptId=(int)$find->fetchColumn();if($receiptId<=0)accounts_fail('PENDING_WHT_CERTIFICATE_NOT_FOUND',404);$evidence=$db->prepare("SELECT id FROM qbook_financial_evidence WHERE id=? AND source_type='WHT_CERTIFICATE' AND source_record_id=?");$evidence->execute([$evidenceId,$receiptId]);if(!$evidence->fetch())accounts_fail('WHT_CERTIFICATE_EVIDENCE_REQUIRED',409);$update=$db->prepare("UPDATE qbook_customer_receipt_allocation_wht SET certificate_status='CERTIFICATE_RECEIVED',certificate_evidence_id=?,certificate_received_at=UTC_TIMESTAMP() WHERE id=? AND certificate_status='CERTIFICATE_PENDING'");$update->execute([$evidenceId,$allocationWhtId]);}else{$find=$db->prepare("SELECT receipt_id FROM qbook_receipt_wht WHERE receipt_id=? AND certificate_status='CERTIFICATE_PENDING' FOR UPDATE");$find->execute([$receiptId]);if(!$find->fetchColumn())accounts_fail('PENDING_WHT_CERTIFICATE_NOT_FOUND',404);$evidence=$db->prepare("SELECT id FROM qbook_financial_evidence WHERE source_type='WHT_CERTIFICATE' AND source_record_id=? LIMIT 1");$evidence->execute([$receiptId]);if(!$evidence->fetch())accounts_fail('WHT_CERTIFICATE_EVIDENCE_REQUIRED',409);$update=$db->prepare("UPDATE qbook_receipt_wht SET certificate_status='CERTIFICATE_RECEIVED',certificate_received_at=UTC_TIMESTAMP() WHERE receipt_id=? AND certificate_status='CERTIFICATE_PENDING'");$update->execute([$receiptId]);}if($update->rowCount()!==1)accounts_fail('PENDING_WHT_CERTIFICATE_NOT_FOUND',404);accounts_audit($db,$user,'WHT_CERTIFICATE_RECEIVED','CUSTOMER_RECEIPT',$receiptId,['allocation_wht_id'=>$allocationWhtId?:null,'evidence_id'=>$evidenceId?:null]);return['status'=>'CERTIFICATE_RECEIVED'];});});
